import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { AuthContext } from '../../context/AuthContext';
import { Link } from 'react-router-dom';
import { FiBriefcase, FiCheckCircle, FiClock, FiXCircle, FiArrowRight, FiDollarSign, FiCalendar } from 'react-icons/fi';

const StudentDashboard = () => {
  const { user } = useContext(AuthContext);
  const [applications, setApplications] = useState([]);
  const [stats, setStats] = useState({ total: 0, accepted: 0, pending: 0, rejected: 0 });
  const [loading, setLoading] = useState(true);
  const [animateIn, setAnimateIn] = useState(false);

  useEffect(() => {
    fetchApplications();
    setTimeout(() => setAnimateIn(true), 100);
  }, []);

  const fetchApplications = async () => {
    try {
      const token = localStorage.getItem('token');
      const res = await axios.get('http://localhost:5000/api/application/student', {
        headers: { 'x-auth-token': token }
      });
      setApplications(res.data);
      calculateStats(res.data);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  const calculateStats = (apps) => {
    setStats({
      total: apps.length,
      accepted: apps.filter(a => a.status === 'accepted').length,
      pending: apps.filter(a => a.status === 'pending').length,
      rejected: apps.filter(a => a.status === 'rejected').length,
    });
  };

  const getStatusColor = (status) => {
    switch(status) {
      case 'accepted': return 'bg-green-100 text-green-700 border-green-300';
      case 'pending': return 'bg-yellow-100 text-yellow-700 border-yellow-300';
      case 'rejected': return 'bg-red-100 text-red-700 border-red-300';
      default: return 'bg-gray-100 text-gray-700 border-gray-300';
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-green-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600 font-medium">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  const statCards = [
    { label: 'Total Applied', value: stats.total, icon: <FiBriefcase size={24}/>, color: 'bg-green-100 text-green-600', bgGradient: 'from-green-50 to-green-100' },
    { label: 'Accepted', value: stats.accepted, icon: <FiCheckCircle size={24}/>, color: 'bg-blue-100 text-blue-600', bgGradient: 'from-blue-50 to-blue-100' },
    { label: 'Pending', value: stats.pending, icon: <FiClock size={24}/>, color: 'bg-yellow-100 text-yellow-600', bgGradient: 'from-yellow-50 to-yellow-100' },
    { label: 'Rejected', value: stats.rejected, icon: <FiXCircle size={24}/>, color: 'bg-red-100 text-red-600', bgGradient: 'from-red-50 to-red-100' },
  ];

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className={`max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 transition-all duration-700 ${animateIn ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
        
        {/* Welcome Header */}
        <div className="mb-8 animate-slide-down">
          <h1 className="text-4xl font-bold text-gray-800 mb-2">Welcome back, {user.name}! 👋</h1>
          <p className="text-gray-600">Here's what's happening with your projects</p>
        </div>

        {/* Stats Cards */}
        <div className="grid md:grid-cols-4 gap-6 mb-8">
          {statCards.map((card, index) => (
            <div key={index} className={`bg-gradient-to-br ${card.bgGradient} rounded-xl p-6 border border-gray-100 shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 animate-scale-in group cursor-pointer`} style={{animationDelay: `${index * 0.1}s`}}>
              <div className="flex items-center justify-between mb-4">
                <div className={`w-12 h-12 ${card.color} rounded-xl flex items-center justify-center group-hover:scale-110 transition-transform duration-300`}>
                  {card.icon}
                </div>
                <div className="text-right">
                  <p className="text-3xl font-bold text-gray-800 group-hover:scale-110 transition-transform duration-300">{card.value}</p>
                </div>
              </div>
              <p className="text-gray-600 font-medium">{card.label}</p>
            </div>
          ))}
        </div>

        {/* Applications Section */}
        <div className="grid md:grid-cols-3 gap-8">
          
          {/* Applications List */}
          <div className="md:col-span-2">
            <div className="flex items-center justify-between mb-6 animate-slide-in-left" style={{animationDelay: '0.2s'}}>
              <h2 className="text-2xl font-bold text-gray-800">My Applications</h2>
              <Link to="/browse" className="flex items-center space-x-2 text-green-600 hover:text-green-700 font-medium text-sm transition-all hover:gap-3 duration-300">
                <span>Browse More</span><FiArrowRight className="transition-transform group-hover:translate-x-1"/>
              </Link>
            </div>

            <div className="space-y-4">
              {applications.length === 0 ? (
                <div className="bg-white rounded-xl p-12 text-center border border-gray-100 animate-fade-in">
                  <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <FiBriefcase className="text-gray-400" size={32}/>
                  </div>
                  <h3 className="text-xl font-bold text-gray-800 mb-2">No Applications Yet</h3>
                  <p className="text-gray-600 mb-6">Start applying to projects to build your portfolio!</p>
                  <Link to="/browse" className="inline-flex items-center space-x-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-all hover:shadow-lg transform hover:scale-105">
                    <span>Browse Projects</span><FiArrowRight/>
                  </Link>
                </div>
              ) : (
                applications.map((app, index) => (
                  <div key={app._id} className="bg-white rounded-xl p-6 border border-gray-100 shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 animate-slide-up group" style={{animationDelay: `${0.1 * (index % 5)}s`}}>
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex-1">
                        <h3 className="text-lg font-bold text-gray-800 mb-1 group-hover:text-green-600 transition-colors">{app.project.title}</h3>
                        <p className="text-gray-600 text-sm line-clamp-2 mb-3">{app.project.description}</p>
                        
                        {/* Skills */}
                        <div className="flex flex-wrap gap-2 mb-3">
                          {app.project.requiredSkills.slice(0, 3).map((skill, i) => (
                            <span key={i} className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs font-medium hover:bg-green-100 hover:text-green-700 transition-all">{skill}</span>
                          ))}
                          {app.project.requiredSkills.length > 3 && <span className="px-2 py-1 bg-gray-100 text-gray-500 rounded text-xs">+{app.project.requiredSkills.length - 3}</span>}
                        </div>

                        {/* Meta */}
                        <div className="flex items-center space-x-4 text-sm text-gray-500">
                          <div className="flex items-center space-x-1"><FiDollarSign size={14}/><span className="font-semibold">${app.proposedBudget}</span></div>
                          <div className="flex items-center space-x-1"><FiCalendar size={14}/><span>{new Date(app.appliedAt).toLocaleDateString()}</span></div>
                        </div>
                      </div>
                      
                      {/* Status Badge */}
                      <div className={`px-4 py-2 rounded-full border font-bold text-sm capitalize ${getStatusColor(app.status)} ml-4 whitespace-nowrap animate-bounce-in`}>
                        {app.status}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            
            {/* Profile Card */}
            <div className="bg-white rounded-xl p-6 border border-gray-100 shadow-sm hover:shadow-lg transition-all animate-slide-in-right" style={{animationDelay: '0.3s'}}>
              <h3 className="text-lg font-bold text-gray-800 mb-4">Your Profile</h3>
              <p className="text-gray-600 text-sm mb-4">Add your skills to get matched with the best projects.</p>
              <Link to="/profile" className="block w-full text-center px-4 py-2.5 bg-gray-900 text-white rounded-lg hover:bg-gray-800 transition-all hover:shadow-lg transform hover:scale-105">
                Update Profile
              </Link>
            </div>

            {/* Quick Links */}
            <div className="bg-white rounded-xl p-6 border border-gray-100 shadow-sm hover:shadow-lg transition-all animate-slide-in-right" style={{animationDelay: '0.4s'}}>
              <h3 className="text-lg font-bold text-gray-800 mb-4">Quick Links</h3>
              <div className="space-y-3">
                {[
                  { to: '/browse', label: 'Browse Projects', icon: <FiBriefcase size={16}/> },
                  { to: '/profile', label: 'Edit Profile', icon: <FiCheckCircle size={16}/> },
                ].map((link, i) => (
                  <Link key={i} to={link.to} className="flex items-center space-x-3 text-gray-700 hover:text-green-600 transition-all hover:translate-x-1 duration-200 group">
                    <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center group-hover:bg-green-100 group-hover:text-green-600 transition-all">
                      {link.icon}
                    </div>
                    <span className="font-medium">{link.label}</span>
                    <FiArrowRight className="ml-auto opacity-0 group-hover:opacity-100 transition-opacity" size={14}/>
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;
